"""Generic region-aware routing (generated by tools/gen_regions.py for EVERY map).

Mt. Moon is the regression case (the overnight run looped ~100 calls in B1F), but the point
is that nothing here is per-cave: any split map is routed the same way.
"""
from collections import deque

from knowledge import map_graph as g
from knowledge.map_graph import MAP_WARPS, node_for, route_to
from knowledge.map_regions import CONN_LINKS, REGION_GRIDS, WARP_ARRIVAL

CERULEAN = (3, 3)
PALLET = (3, 0)


def _warps(route):
    return [s[1] for s in route if s[0] == "warp"]


def test_mt_moon_route4_west_to_cerulean():
    r = route_to(node_for(3, 22, 19, 5), CERULEAN)
    # 1F -> B1F (west region) -> B2F -> B1F (exit region) -> Route 4 east -> Cerulean
    assert _warps(r) == [(19, 5), (5, 6), (22, 18), (5, 10), (45, 4)]
    assert r[-1][:2] == ("connection", "East")


def test_mt_moon_b1f_ladder_region_goes_down_not_to_the_exit():
    """The exact spot the run got stuck: B1F (3,3)."""
    r = route_to(node_for(1, 2, 3, 3), CERULEAN)
    assert _warps(r) == [(22, 18), (5, 10), (45, 4)]


def test_route4_pokemon_center_exits_to_the_west_half():
    r = route_to((16, 0), CERULEAN)
    assert r is not None and _warps(r)[0] == (6, 8)


def test_route2_goes_through_viridian_forest():
    r = route_to((3, 1), (3, 2))     # Viridian -> Pewter
    # The Route 2 gate building looks reachable on the tiles but sits behind a Cut tree
    # (an object), so the strict graph must go forest: south entrance, forest, north entrance.
    assert _warps(r) == [(5, 51), (7, 1), (5, 9), (7, 1)]


def test_grid_tags_are_consistent_with_arrival_and_link_tables():
    for mp, rows in REGION_GRIDS.items():
        assert len({len(r) for r in rows}) == 1
    tags = {mp: {c for r in rows for c in r if c != "#"} for mp, rows in REGION_GRIDS.items()}
    for (_src, _xy), (dst, tag) in WARP_ARRIVAL.items():
        assert tag in tags[dst]
    for (src, _d, dst), pairs in CONN_LINKS.items():
        for a, b in pairs:
            assert a is None or a in tags[src]
            assert b is None or b in tags[dst]


def test_every_split_maps_warp_has_a_departure_region():
    for mp in REGION_GRIDS:
        for (x, y, _dest) in MAP_WARPS.get(mp, []):
            assert g._departure_tags(mp, x, y)


def _reach(start):
    seen, q = {start}, deque([start])
    while q:
        c = q.popleft()
        nxt = [n for _d, n in g._R_CONN.get(c, [])] + [n for _x, _y, n in g._R_WARP.get(c, [])]
        for n in nxt:
            if n not in seen:
                seen.add(n)
                q.append(n)
    return {n[:2] for n in seen}


def test_puzzle_dungeons_are_reachable_through_the_strict_graph():
    """Rock Tunnel, Pokémon Tower and the Silph Co. floors are connected purely by warps /
    teleporters, so the strict region graph (no HM assumptions) must reach them."""
    reach = _reach(PALLET)
    for mp in [(1, 81), (1, 82), (1, 88), (1, 94), (1, 47), (1, 48)]:
        assert mp in reach, mp


def test_hm_gated_areas_fall_back_to_the_coarse_graph():
    """Victory Road / Seafoam need Surf/Strength the tiles can't express: the strict graph
    says unreachable, but route_to still returns the optimistic coarse route (never worse
    than before regions existed)."""
    assert (1, 83) not in _reach(PALLET)
    assert route_to(PALLET, (1, 83)) is not None


def test_learned_blocked_edges_reroute():
    r = route_to(node_for(3, 22, 19, 5), CERULEAN)
    first = r[0]
    start = node_for(3, 22, 19, 5)
    alt = route_to(start, CERULEAN, avoid_edges={(start, first[0], first[1])})
    assert alt is None or alt[0][:2] != first[:2]
